import collections

def mru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Most Recently Used (MRU)
    algorithm.

    :param maxsize: The maximum number of items to store in the cache.
    :param typed: If True, the cache keys are hashable instead of custom
                  hashable, meaning that the same function with different
                  variable types will be cached separately.

    :returns: A wrapped function that memoizes its results based on the MRU algorithm or else a function wrapper that does this.
    """
    def decorator(func):
        if func is None:
            return functools.partial(mru_cache, maxsize=maxsize, typed=typed)

        if not inspect.isfunction(func):
            raise ValueError('The @mru_cache decorator must be applied innermost of all decorators.')

        cache = collections.OrderedDict(maxlen=maxsize)

        @functools.wraps(func)
        def memoize(*args, **kwargs):
            # Combine args and kwargs into a single hashable key
            cache_key = functools.make_key((args, kwargs))
            if cache_key in cache:
                return cache[cache_key]
            result = func(*args, **kwargs)
            cache[cache_key] = result
            return result

        @functools.wraps(func)
        def forward_cache(*args, **kwargs):
            if cache_key in cache:
                return cache[cache_key]
            result = func(*args, **kwargs)
            cache.appendleft(cache_key)  # Move key to the front
            return result

        @functools.wraps(func)
        def backward_cache(*args, **kwargs):
            if cache_key in cache:
                result = func(*args, **kwargs)
                cache.remove(cache_key)  # Remove key from the end
                return result
            result = func(*args, **kwargs)
            cache.append(cache_key)  # Add key back to the end
            return result

        def clear():
            cache.clear()

        return memoize, forward_cache, backward_cache, clear

    return decorator

def mru_cache(maxsize=128, typed=False):
    """
    Decorator to wrap a function with a memoizing callable that saves up to `maxsize` results based on a Most Recently Used (MRU) algorithm.

    Args:
    maxsize (int): The maximum number of results to cache. Defaults to 128.
    typed (bool): If True, results for arguments of different types will be treated as distinct. Defaults to False.

    Returns:
    function wrapper: A wrapped function that memoizes its results or else a function wrapper that does this.
    """
    def decorator(func):
        results = [] if typed else {}
        cache = {func(*args): v for args, v in results}
        memoized_results = cache

        @functools.wraps(func)
        def memoize(*args, **kwargs):
            key = (func, *args, tuple(kwargs.items()))
            if key in memoized_results:
                return memoized_results[key]
            result = func(*args, **kwargs)
            memoized_results[key] = result
            if len(memoized_results) > maxsize:
                oldest_key = min(memoized_results, key=memoized_results.get)
                if not typed:
                    del results[oldest_key]
                else:
                    del results[type(oldest_key)][oldest_key]
            return result

        @contextmanager
        def put(*args, **kwargs):
            key = (func, *args, tuple(kwargs.items()))
            yield functools.partial(memoized_results.__setitem__, key)
        memoize.put = put

        def forget(*args, **kwargs):
            key = (func, *args, tuple(kwargs.items()))
            if key in memoized_results:
                del memoized_results[key]
        memoize.forget = forget

        def clear():
            memoized_results.clear()
            results.clear()
        memoize.clear = clear

        return memoize

    return decorator

def lru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm.

    """
    if maxsize == 0:
        return lambda fn: fn

    def decorator(fn):
        cache = {}  # Dictionary to store memoized results

        def wrapper(*args, **kwargs):
            key = args, frozenset(kwargs.items())  # Unique key for the cached result
            if key in cache:
                return cache[key]  # Return the cached result
            result = fn(*args, **kwargs)  # Call the function
            if isinstance(result, dict):
                for k, v in result.items():
                    # Only store items with dict keys
                    if isinstance(k, dict):
                        cache[key] = result  # Store the result
                        break  # Break after storing the first dict result
            else:
                cache[key] = result  # Store the result
            return result

        return wrapper
    return decorator

