def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    if coord_name not in self.errors:
        raise KeyError(f'Error variable {coord_name} not found.')
    if self.errors[coord_name] is None:
        self.errors[coord_name] = {}
    err_indices = {k: None for k in self.data.dims}
    for d, var in self.errors[coord_name].items():
        for Slice in var.slices_like(d):
            cdims = var.sizes[d]
            indices = np.where(Slice.all())[0]
            if index is not None:
                err_indices[d] = indices
    return err_indices

