def _update_context(self, context):
    context.error.extend([(i, err_index) for i, err_index in enumerate(self.errors)])
    levels = self.levels
    attrs = {'x': 'value.x', 'y': 'value.y', 'z': 'value.z'}
    used_attrs = attrs.keys() if not levels else levels
    for attr in used_attrs:
        ctx_value = context.value
        ctx_subctx = context
        while ctx_value:
            context_value = context_value[attrs[attr]]
            if ctx_subctx is not context_value:
                if attr == 'x' and not isinstance(context_value, list):
                    context_value = [context_value]
                ctx_subctx[attr] = context_value
        if not levels:
            context.error.extend([(i, err_index) for i, err_index in enumerate(self.error_unlevels)])

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    def is_element(seq):
        return isinstance(seq, FillRequest)

    def has_fill_request(seq):
        for item in seq:
            if is_element(item):
                return True

        return False

    return is_element(seq) or has_fill_request(seq) and not isinstance(seq, SourceSeq)

