from copy import deepcopy

def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion, set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    if level == -1:
        return deepcopy(d1)
    difference_dict = {}
    for key in d1:
        if key not in d2:
            if isinstance(d1[key], (dict, list)) and level > 0:
                if isinstance(d1[key], list):
                    sub_d1 = [ difference(item, d2.get(item), level - 1) for item in d1[key] ]
                    if all(isinstance(item, (list, dict)) for item in sub_d1):
                        difference_dict[key] = sub_d1
                    else:
                        # If any sub-item is not a list or dictionary, skip this key
                        continue
                elif isinstance(d1[key], dict):
                    sub_d1 = difference(d1[key], d2.get(key), level - 1)
                    if isinstance(sub_d1, dict):
                        difference_dict[key] = sub_d1
                    else:
                        # If the sub-item is not a dictionary, skip this key
                        continue
            else:
                difference_dict[key] = d1[key]
    return difference_dict

def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    if level == -1 or level == 0:
        return {}
    else:
        diff = {}
        for k in d1:
            if k not in d2:
                diff[k] = d1[k]
            elif isinstance(d1[k], dict) and isinstance(d2[k], dict):
                diff[k] = difference(d1[k], d2[k], level - 1)
            else:
                if d1[k] != d2[k]:
                    diff[k] = d1[k]
        return diff

def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    # Perform a recursive comparison
    def compare_dicts(d1, d2, level=level):
        diff = {}
        for key in set(d1) | set(d2):
            if key == '__class__':
                continue
            if key in d1 and key not in d2:
                diff[key] = d1[key]
            elif key in d2 and key not in d1:
                diff[key] = d2[key]
            elif isinstance(d1[key], dict) and isinstance(d2[key], dict) and level > 0:
                sub_diff = compare_dicts(d1[key], d2[key], level - 1)
                if sub_diff:
                    diff[key] = sub_diff
        return diff

    return compare_dicts(d1, d2, level)

def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    diff = copy.deepcopy(d1)
    for key in d2:
        if key in diff:
            if isinstance(diff[key], dict) and isinstance(d2[key], dict):
                if level != -1:
                    diff[key] = difference(diff[key], d2[key], level - 1)
                else:
                    diff[key] = {k: diff[key][k] for k in d2[key] if diff[key][k] != d2[key][k]}
            elif isinstance(diff[key], list) and isinstance(d2[key], list):
                set_diff = set(d2[key]) - set(diff[key])
                for item in set_diff:
                    diff[key].append(item)
            elif diff[key] != d2[key]:
                diff[key] = copy.deepcopy(d2[key])
    return diff

def difference(d1, d2, level=-1, deep_copy=False):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    if level == -1:
        return {k: v for k, v in d1.items() if k not in d2}
    else:
        diff = {}
        for k, v in d1.items():
            if k not in d2:
                diff[k] = v
                if deep_copy:
                    diff[k] = v.copy() if isinstance(v, dict) else v
            elif isinstance(v, dict):
                result = difference(v, d2[k], level - 1, deep_copy=deep_copy)
                if result:
                    diff[k] = result
        return diff

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    if coord < self.edges[0]:
        return
    if coord >= self.edges[-1]:
        return
    index = np.searchsorted(self.edges, coord, side='right') - 1
    self.hist[index] += weight

def _validate_labels(labels):
    messages = []
    for key, value in labels.items():
        if isinstance(key, str) or isinstance(value, str):
            regex = labels.get(key, "")
            if regex and not re.match(regex, value):
                messages.append({"key": key, "value": "expected string or bytes-like object"})
        elif isinstance(key, bool):
            if not isinstance(value, bool):
                messages.append({"key": key, "value": "expected string or bytes-like object"})
        elif isinstance(key, int) or isinstance(key, float):
            if not isinstance(value, (int, float)):
                messages.append({"key": key, "value": "expected string or bytes-like object"})
        else:
            messages.append({"key": key, "value": "invalid label key or value type"})
    if messages:
        raise ValidationError(messages)

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.

            .. code:: python

                # Example:
                labels = {
                    "key1": "valid",
                    "key2": ["invalid"],
                    "$$": "invalid",
                    True: True,
                }
                try:
                    _validate_labels(labels)
                except ValidationError as err:
                    assert err.messages == [
                        {"['invalid']": 'expected string or bytes-like object'},
                        {'$$': "Label key '$$' does not match the regex [...]"},
                        {'True': 'expected string or bytes-like object'},
                        {'True': 'expected string or bytes-like object'},
                    ]
    """
    messages = []
    for key, value in labels.items():
        if isinstance(key, str) and key[0] == "$":
            if not re.match(r"\$\w+", key):
                message = f"Label key '{key}' does not match the regex \${...\}d"
                messages.append({"['key']": message})
        elif isinstance(value, list):
            for item in value:
                if not isinstance(item, str) and not isinstance(item, bytes):
                    message = f"Invalid value '{item}' for key '{key}'. Expected string or bytes-like object"
                    messages.append({"['item']": message})
        elif not isinstance(value, str) and not isinstance(value, bytes):
            message = f"Invalid value '{value}' for key '{key}'. Expected string or bytes-like object"
            messages.append({"['key']": message})
    if messages:
        raise ValidationError(messages)

try:
        for key, value in labels.items():
            # Check if key starts with a letter
            if not key[0].isalpha():
                raise ValidationError({"key": f"Label key '{key}' does not start with a letter"})
            # Check if value matches the regular expression '^[a-z0-9]*$'
            if not isinstance(value, str) or not re.match("^[a-z0-9]*$", value):
                raise ValidationError({"value": f"Value '{value}' for key '{key}' does not match the regex '[a-z0-9]*$'"})
    except KeyError:
        raise ValidationError({
            "key": "One of the keys in the labels doesn't exist in the provided list"
        })
    except ValidationError as e:
        raise ValidationError(e.messages)

def validate_value(value):
    """
    Validate the given value against the corresponding regular expression.

    Args:
        value: the string to validate

    Raises:
        ValidationError: if the given value is not conform to the regular expression.
    """
    if not value:
        return e("{} is empty", value)

    pattern = self.regex
    if not pattern:
        return e("Nothing was defined.")

    regex = re.compile(pattern)

    def validate(value):
        if not regex.match(value):
            return e("{} does not match the pattern {}", value, pattern)
    return validate

def generate_default_observer_schema(app):
    """
    Generate the default observer schema for each Kubernetes resource present in ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a default observer schema
    """
    resource_types = {resource.metadata.name: resource for resource in app.spec.manifest}
    default_schemas = {}

    for resource_name, resource in resource_types.items():
        if resource.metadata.labels.get('krake.io/observer-schema', '') == '':
            default_schemas[resource_name] = generate_default_schema(resource)
            print(f"Generated default observer schema for {resource_name}")

    return default_schemas

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """

    default_observer_schemas = {}

    # Iterate through each manifest resource in the application's manifest
    for resource in app.manifest:
        # Verify if a default observer schema for the resource is available in the schema provider
        if resource in app.schema_provider.default_observer_schemas:
            default_observer_schemas[resource] = app.schema_provider.default_observer_schemas[resource]
        else:
            # Calculate default observer schema for the resource
            operator_overrides = {k: resource[key] for k in resource if 'operator_override' in resource}
            spec_overrides = {k: resource[key] for k in resource if 'spec_override' in resource}
            default_observer_schema = app.schema_provider.calculate_default_observer_schema(resource, operator_overrides, spec_overrides)
            default_observer_schemas[resource] = default_observer_schema

    return default_observer_schemas

