def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    manifest_files_present = set()
    for file in manifest_files:
        manifest_files_present.add(os.path.basename(file))

    missing_digests = set(digests_used)
    for digest in manifest_files_present:
        if digest not in digests_used:
            missing_digests.remove(digest)

    for digest in digests_used:
        if digest not in manifest_files_present:
            raise ValueError(f"Digest {digest} is needed but not present.")

    for digest in missing_digests:
        raise ValueError(f"Digest {digest} is used but not present.")

def check_digests_present_and_used(self, manifest_files, digests_used):
