def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not fixity:
        raise ValueError("Fixity block cannot be empty")

    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary")

    for file_path, expected_hash in fixity.items():
        if file_path not in manifest_files:
            raise ValueError(f"Reference to unlisted file: {file_path}")

        # Check the hash of the file
        file_path = os.path.join(self.inventory_dir, file_path)
        with open(file_path, 'rb') as f:
            actual_hash = hashlib.sha256(f.read()).hexdigest()
        if actual_hash != expected_hash:
            raise ValueError(f"Hash mismatch for file {file_path}")

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    for key, checksum in fixity.items():
        if key not in manifest_files:
            raise ValueError(f"File '{key}' is not listed in the manifest.")
    required_files = {key for key, _ in fixity.items()}
    if required_files != set(manifest_files):
        missing_files = required_files - set(manifest_files)
        extra_files = set(manifest_files) - required_files
        if missing_files:
            raise ValueError(f"Missing files: {missing_files}")
        if extra_files:
            raise ValueError(f"Extra files: {extra_files}")

