def files_list(path):
    ret = []
    # Iterate through the path and check if each item is a file or directory
    for item in os.listdir(path):
        item_path = os.path.join(path, item)
        if os.path.isfile(item_path):
            ret.append(item_path)
        elif os.path.isdir(item_path):
            # Recursively collect files from directories
            ret += [item for subitem in files_list(item_path) if os.path.isfile(subitem)]

    return ret

