def _explore_folder(self, folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
    """
    data = {}
    for root, _, files in os.walk(folder):
        for f in files:
            if f.endswith('.xml'):
                basename = os.path.splitext(f)[0]
                if basename in data:
                    data[basename].extend([os.path.join(root, f)])
                else:
                    data[basename] = [os.path.join(root, f)]
    return data

def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
    """
    packages_data = {}

    if not folder:
        return packages_data

    for root, dirs, files in os.walk(folder):
        for file in files:
            file_path = os.path.join(root, file)
            file_basename = os.path.splitext(file)[0]
            if file_basename.endswith('.xml'):
                file_content = open(file_path, 'rb').read()
                if file_basename in packages_data:
                    packages_data[file_basename].append(file_content)
                else:
                    packages_data[file_basename] = [file_content]

    return packages_data

def _explore_folder(folder):
    guard = re.compile(r'^[^\.]+\.xml$', re.IGNORECASE)
    files = []
    for root, dirs, files in os.walk(folder):
        relative_folder = re.sub(r'^/',
                                     '',
                                     root.replace(folder, ''))

        for name in files:
            if guard.search(os.path.basename(name)) and not name.startswith('.') and name.endswith('.xml'):
                files.append(os.path.join(root, name))

    return {
        '{}/{}'.format(relative_folder, name): os.path.join(root, name)
        for name in files
    }

def add_rendition(self, lang, file_path):
    """
    {
        "original": "artigo02.pdf",
        "en": "artigo02-en.pdf",
    }
    """
    if len(file_path.split('.')) < 2:
        raise ValueError("Invalid file path format. Expected a file name and extension.")

    original_filename, file_extension = file_path.rsplit('.', 1)

    # Strip away illegal characters from filenames
    valid_filename = re.sub(r'[^\w\s\-_.]', '', original_filename)

    # Generate the targeted file path with the original extension
    rendition_path = f"{valid_filename}-{lang}.{file_extension}"

    # Create the output to be returned
    re hypothesis = {
        "original": file_path,
        "en": rendition_path
    }

    return re hypothesis

