def zip_context(zip_path):
    with zipfile.ZipFile(zip_path) as zin:
        yielded_dict = {}
        for zinfo in zin.infolist():
            file_name = zinfo.filename
            if file_name.endswith('/'):
                yielded_dict[file_name] = {}
            else:
                max_lines = 1000
                yielded_dict[file_name].update({
                    line.strip() for line in zin.read(file_name).splitlines()[:max_lines]
                })
    yield yielded_dict

