            raise ValueError("Input datetime is not timezone-aware")

        utc = pytz.utc

        # Calculate the offset from UTC
        utc_offset = utc.fromutc(dt) - dt

        # Get the timezone object from the offset
        new_timezone = utc_offset.tzinfo

        if new_timezone is None:
            raise ValueError("No timezone information could be inferred from the input datetime")

        # Convert logical timezone
        if dt.utcoffset() == 0:
            logical_utc = datetime(1970, 1, 1, 0, 0, 0, tzinfo=utc)
            logical_timezone = new_timezone
        else:
            logical_utc = dt.astimezone(utc)
            logical_timezone = None

        returnUtc = dt.astimezone(new_timezone)

        if logical_timezone is not None and logical_utc.date().day == dt.date().day:
            return logical_utc
        else:
            return returnUtc

from datetime import timedelta

class Relativedelta:
    def __init__(self, days=0, seconds=0, microseconds=0, milliseconds=0,
                 minutes=0, hours=0, weeks=0):
        self.days = days
        self.seconds = seconds
        self.microseconds = microseconds
        self.milliseconds = milliseconds
        self.minutes = minutes
        self.hours = hours
        self.weeks = weeks

    def __eq__(self, other):
        return isinstance(other, Relativedelta) and other.days == self.days and other.seconds == self.seconds and other.microseconds == self.microseconds and other.milliseconds == self.milliseconds and other.minutes == self.minutes and other.hours == self.hours and other.weeks == self.weeks

    def __hash__(self):
        return hash((self.days, self.seconds, self.microseconds, self.milliseconds, self.minutes, self.hours, self.weeks))

    def __ne__(self, other):
        return not self == other

    def __add__(self, other):
        if isinstance(other, timedelta):
            return Relativedelta(days=self.days + other.days, seconds=self.seconds + other.seconds, microseconds=self.microseconds + other.microseconds, milliseconds=self.milliseconds + other.milliseconds, minutes=self.minutes + other.minutes, hours=self.hours + other.hours, weeks=self.weeks + other.weeks)
        elif isinstance(other, Relativedelta):
            return Relativedelta(days=self.days + other.days, seconds=self.seconds + other.seconds, microseconds=self.microseconds + other.microseconds, milliseconds=self.milliseconds + other.milliseconds, minutes=self.minutes + other.minutes, hours=self.hours + other.hours, weeks=self.weeks + other.weeks)
        else:
            raise TypeError("Unsupported operand type(s) for +: 'Relativedelta' and '%s'" % type(other).__name__)

    def __sub__(self, other):
        if isinstance(other, timedelta):
            return Relativedelta(days=self.days - other.days, seconds=self.seconds - other.seconds, microseconds=self.microseconds - other.microseconds, milliseconds=self.milliseconds - other.milliseconds, minutes=self.minutes - other.minutes, hours=self.hours - other.hours, weeks=self.weeks - other.weeks)
        elif isinstance(other, Relativedelta):
            return Relativedelta(days=self.days - other.days, seconds=self.seconds - other.seconds, microseconds=self.microseconds - other.microseconds, milliseconds=self.milliseconds - other.milliseconds, minutes=self.minutes - other.minutes, hours=self.hours - other.hours, weeks=self.weeks - other.weeks)
        else:
            raise TypeError("Unsupported operand type(s) for -: 'Relativedelta' and '%s'" % type(other).__name__)

