                raise ValueError(msg)
        else:
            if verbose:
                print(output.decode())

import subprocess

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""

    command_list = []

    for index, (command_parts, arg_list) in enumerate(zip(commands, args)):
        command = f"{command_parts} " + " ".join(arg_list)
        command_list.append(command)

    output = None
    try:
        command_string = " ".join(command_list)
        if hide_stderr:
            stderr = subprocess.PIPE
        else:
            stderr = subprocess.STDOUT

        if cwd:
            stdout = subprocess.PIPE, subprocess.Popen(['pwd'], stdout=subprocess.PIPE).communicate()[0].decode() + '\n'
        else:
            stdout = subprocess.PIPE

        output = subprocess.check_output(command_string, stderr=stderr, shell=False, cwd=cwd, env=env)
    except subprocess.CalledProcessError as e:
        if verbose:
            print(f"Failed to run command: {command_string}")
            print(e.stderr.decode())
        else:
            print(f"Failed to run command.")

    return output.decode()

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    for command in commands:
        command_list = [command]
        for arg in args:
            command_list.append(arg)
        if cwd:
            command_list.insert(0, f'cd {cwd}')
        if env:
            command_list.insert(0, f'export {env}')

        if verbose:
            print('Running command:', command_list)

        if hide_stderr:
            subprocess.run(command_list, capture_output=True, text=True, env=env)
        else:
            subprocess.run(command_list, text=True, env=env)

