def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    last_char = version[-1]
    if last_char.isdigit():
        last_digits = int(version[-len(last_char):])
        return version[:-len(last_char)] + str(last_digits + 1)
    else:
        return version + '1'

def next_version(version):
    """
    Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    version = version.lstrip("0")
    version_number = int(version)

    if version_number == 0:
        return "1"
    return str(version_number + 1)

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if version.lstartswith('0'):
        return '1'
    elif version.isnumeric():
        parts = list(map(int, version.split('.')))
        parts[-1] += 1
        return '.'.join(str(part) for part in parts)
    return '1.0.0'

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    version_lookup = {dir_name: InventoryLoader(self.specs, dir_name) for dir_name in version_dirs}
    for dir_name in version_dirs:
        inventory = version_lookup[dir_name]
        if not inventory.exists():
            raise FileNotFoundError(f"Version inventory {dir_name} not found.")
            if not inventory.is_valid():
                raise ValueError(f"Invalid version inventory {dir_name}.")
        content_digest = inventory.get_content_digest()
        if content_digest != self.content_digest:
            self.content_digests.append(content_digest)

