        so that we can also check them when validating the content.

        version_dirs is an array of version directory names and is assumed to be in
        version sequence (1, 2, 3...).
    """
    versions = version_dirs
    if not versions:
        raise ValueError('Versions list is empty.')
    if versions[0] != '1':
        raise ValueError('The first version should be 1.')
    if len(versions) < 2:
        raise ValueError('There should be at least two versions.')
    for i in range(len(versions) - 1):
        if versions[i+1] - versions[i] != 1:
            raise ValueError('Versions should be in a sequential order.')
    for version in versions:
        inventory_path = f"{self.root_inventory_path}/{version}"
        if not os.path.exists(inventory_path):
            raise ValueError(f"Inventory file for version {version} does not exist.")

