def amend_bzparams(self, params, bug_ids):
    """
    Amend the Bugzilla params

    :param params: A dictionary containing the new parameters to be updated.
    :param bug_ids: A list of bug IDs for which the parameters should be amended.
    """
    for bug_id in bug_ids:
        url = f'https://bugzilla.cloudburst.com/rest/bug/{bug_id}'
        data = {
            'changes': [{'add': {'field_name': field, 'value': params[field]} for field in params} for field in params]
        }
        response = requests.put(url, json=data, headers={'Content-Type': 'application/json'})
        if response.status_code != 200:
            raise BugzillaException(f'Failed to update bug {bug_id}: {response.text}')

