    """
        Amend the Bugzilla params

        :param params: A dictionary where keys are bug ids and values are a dictionary with the parameter updates
        :param bug_ids: A list of bug ids to update
    """
    for bug_id, update_dict in params.items():
        if bug_id in bug_ids:
            for key, value in update_dict.items():
                if key in bug_id.bug:
                    bug_id.bug[key] = value

