def parse_arguments(*unparsed_arguments):
    """Given command-line arguments with which this script was invoked, parse the arguments and return
    them as a dict mapping from subparser name (or "global") to an argparse.Namespace instance.
    """
    parsed_args = {}
    subparser_index = 0
    for i, arg in enumerate(unparsed_arguments):
        if subparser_index == 0 and arg == '--':
            subparser_index = 1

    if subparser_index == 0:
        # If no subparsers are specified, the first argument is considered as the global argument
        parsed_args['global'] = argparse.Namespace()
        parsed_args['global'].args = unparsed_arguments[1:]
        return parsed_args

    current_subparser = None
    for i, arg in enumerate(unparsed_arguments):
        if i == subparser_index and arg == '--':
            subparser_index = subparser_index + 1

    for i, arg in enumerate(unparsed_arguments):
        if i == subparser_index:
            if current_subparser is None:
                current_subparser = argparse.ArgumentParser()
            parsed_args[current_subparser.name] = current_subparser.parse_args(arg.split())
            subparser_index = subparser_index + 1

    if current_subparser is None:
        raise ValueError("No subparsers specified in the arguments.")

    return parsed_args

