def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    size_value = float(size.strip().replace('M', '000').replace('K', '000'))
    if size.endswith('B'):
        return size_value
    if size.endswith('K'):
        return int(size_value * 1000)
    if size.endswith('M'):
        return int(size_value * 1000000)
    if size.endswith('G'):
        return int(size_value * 1000000000)
    if size.endswith('T'):
        return int(size_value * 1000000000000)

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    return {k: sum(d[k] for d in dicts) for k, v in next(dicts).items()}

