    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    result = dict()
    for d in dicts:
        for k, v in d.items():
            cumul = result.get(k, 0)
            result[k] = cumul + v
    return result

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    result = {}
    for d in dicts:
        if not d:
            continue
        for key, value in d.items():
            if key in result:
                result[key] += value
            else:
                result[key] = value
    return result

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""
    if not url:
        return ''

    p = urlsplit(url)
    qs = parse_qs(p.query)
    for k, v in six.iteritems(url_args):
        if k in qs.setlist:
            qs[k].extend(v)
        else:
            qs[k].append(v)
    p = urlunsplit((p[0], p[1], urlencode(qs, doseq=True), p[4]))
    return p

