    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    import shlex
    from platform import sys

    if platform == 'this':
        platform = {'this': sys.platform.replace('.', '_'), 'Windows': 'Windows', 'Cmd': 'cmd'}.get(sys.platform, sys.platform)

    if platform == 'posix':
