def _resolve_string(matcher):
    '''Args:
        matcher: A dictionary containing a name and an optional default value.
    Returns:
        The value associated with the матери as ``str``.
    Raises:
        KeyError: If the ``name`` is not found in the ``matcher``.
    '''
    if 'name' not in matcher:
        raise KeyError('A name must be provided in the matcher.')
    name = matcher['name']
    if 'default' in matcher:
        default = matcher['default']
    else:
        default = None
    if name not in os.environ:
        if default is not None:
            return default
        raise KeyError(f'The environment variable "{name}" is not found.')
    return os.environ[name]

def _resolve_string(self, matcher):
        name, default = matcher.split('=')
        name = name.strip()
        default = default.strip() if default else None
        if name not in self.environ:
            if default is not None:
                return default
            raise EnvironmentError('Environment variable %s not found', name)
        return self.environ[name]

