            if property in graph Triples(node):
                for sibling in graph.ObjectsOf((node, property)):
                    stack.append((sibling, rdflib.RDFS.subClassOf, None))

    for node, parent in graph.NodeTriples():
        if parent is None and node not in roots:
            roots.add(node)

    return roots

