def verifyObject(iface, candidate, tentative=False):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
    interface using ``iface.providedBy`` (unless *tentative* is `True`,
    in which case this step is skipped). This means that the candidate's class
    declares that it `implements <zope.interface.implementer>` the interface,
    or the candidate itself declares that it `provides <zope.interface.provider>`
    the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
    extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
    checked passed.
    :raises zope.interface.Invalid: If any of the previous
    conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """
    if not tentative and iface is not providedBy(candidate):
        raise zope.interface.Invalid("The candidate does not claim to implement the desired interface.")

    for method in iface.implementedMethods():
        if not hasattr(candidate, method):
            raise zope.interface.Invalid("The candidate does not implement the method %s." % method)

    for attribute, descriptor in iface._attributes.items():
        if not hasattr(candidate, attribute):
            raise zope.interface.Invalid("The candidate does not define the attribute %s." % attribute)
        if descriptor.kind == 'class':
            candidate_attribute = getattr(candidate, attribute)
            if not issubclass(candidate_attribute, descriptor.originalClass):
                raise zope.interface.Invalid("The candidate does not provide the same class type for the attribute %s." % attribute)
        elif descriptor.kind == 'method':
            candidate_method = getattr(candidate, attribute)
            if candidate_method.__code__.co_argcount != descriptor.originalFunction.__code__.co_argcount:
                raise zope.interface.Invalid("The candidate does not have the same number of arguments for the method %s." % attribute)
            if not candidate_method.__defaults__ == descriptor.originalFunction.__defaults__:
                raise zope.interface.Invalid("The candidate does not have the same default arguments for the method %s." % attribute)
            if not candidate_method.__kwdefaults__ == descriptor.originalFunction.__kwdefaults__:
                raise zope.interface.Invalid("The candidate does not have the same keyword defaults for the method %s." % attribute)

    records = inspect.getmembers(candidate, lambda v: isinstance(v, (MethodType, FunctionType)))

    for name, value in records:
        original = getattr(iface, name, None)
        if original:
            if original.__defaults__ and original.__defaults__ != value.__defaults__:
                raise zope.interface.Invalid("The default argument values for the attribute %s in the candidate do not match." % name)
            if original.__kwdefaults__ and original.__kwdefaults__ != value.__kwdefaults__:
                raise zope.interface.Invalid("The keyword default values for the attribute %s in the candidate do not match." % name)

    return True

for param in iface.parameters:
        if param not in candidate.parameters:
            error_message = 'Missing parameter: `{}`'.format(param)
            raise VerifyClassError(error_message)
        candidate_param = candidate.parameters[param]
        if candidate_param.data_type != iface.parameters[param].data_type:
            error_message = 'Parameter `{}` has a mismatched data type.'.format(param)
            raise VerifyClassError(error_message)
        if not isinstance(candidate_param.value, iface.parameters[param].subtype):
            error_message = 'Parameter `{}` has a mismatched subtype.'.format(param)
            raise VerifyClassError(error_message)

    if tentative:
        return
    missing_params = [param for param in iface.parameters if param not in candidate.parameters]
    if missing_params:
        error_message = 'The following parameters are missing: `{}`'.format(', '.join(missing_params))
        raise VerifyClassError(error_message)

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.

    Args:
        iface: The interface that we need to verify.
        candidate: The instance we are verifying against.
        tentative: If the verification is tentative, it means that some parts are unknown and they are allowed to fail.
    """
    # Reach into the candidate for the interface
    if iface and candidate:
        for attr, _ in iface.attributes().items():
            # Retrieve the implementation that implements the attribute
            impl = None
            for method in candidate.__class__.__dict__.values():
                if method not in candidate.__class__.__bases__ and callable(method):
                    attr_name = method.__name__
                    if attr_name == attr and hasattr(method, '_' + attr_name):
                        impl = getattr(method, '_' + attr_name)
                        break
            # Call the implementation to check if it matches the expected behavior
            if not impl or impl() != iface:
                if tentative:
                    # We can skip verification for this attribute
                    print(f'Tentatively skipping verification of attribute: {attr}')
                else:
                    # We raise an exception if the verification fails
                    raise NotImplementedError(f'Attribute: {attr} does not implement the interface: {iface}')
