class Dictator:
    def __init__(self):
        self._redis = None   # Assume _redis attribute is already initialized
        self._head = deque()
        self._tail = self._head
        self._size = 0

    def _find_lt(self, value):
        prev = None
        current = self._head
        while current is not self._tail and current[0] < value:
            prev = current
            current = current[1]

        self._head[1] = current

    def _remove(self, node):
        if node[0] == self._head[0]:
            self._head = node[1]
        else:
            prev[1] = node[1]
        self._size -= 1

    def pop(self):
        """Remove and return the `(key, value)` pair most recently used."""
        if self._head is self._tail:
            raise KeyError('list is empty')

        self._find_lt(self._tail[0])
        if self._head[1] is self._tail:
            self._head = None
        else:
            self._head[1] = self._tail[1]
        self._tail = self._head[1]
        self._size -= 1

        return (self._head[0], self._head[1][0])

