def parse(self, timestr, default=None,
              ignoretz=False, tzinfos=None, **kwargs):
    if ignoretz:
        return self._parse(timestr, default=default, tzinfos=[UTC], **kwargs)
    elif isinstance(timestr, datetime):
        if not timestr.tzinfo:
            timestr = timestr.replace(tzinfo=UTC)
        return timestr
    elif isinstance(timestr, (int, float)):
        multiplied = float(timestr) * 86400
        timestamp = datetime.utcfromtimestamp(multiplied)
        if not timestamp.tzinfo:
            timestamp = timestamp.replace(tzinfo=UTC)
        return timestamp
    else:
        if isinstance(timestr, str):
            for format in self._date_format:
                try:
                    return datetime.strptime(timestr, format)
                except ValueError:
                    continue
        elif isinstance(timestr, bytes):
            return self._parse(timestr.decode(), default=default, **kwargs)
        elif isinstance(timestr, dict):
            return self._parse(timestr, default=default, **kwargs)
        else:
            raise TypeError(" unacceptable input type: %r" % type(timestr))

