def verify_relayable_signature(self, public_key, doc, signature):
    try:
        # Parse the XML document
        root = ET.fromstring(doc)

        # Check if the XML document has the 'signature' element
        if 'Signature' not in root:
            raise ValidationError("No 'Signature' element in the document")

        # Check if the 'Signature' element is valid
        signature_metadata = root.find('Signature').find('SignedInfo')
        if not signature_metadata:
            raise ValidationError("No 'SignedInfo' element in the 'Signature' element")

        # Check if the 'SignedInfo' element has the 'SignatureValue' element
        if not signature_metadata.find('SignatureValue'):
            raise ValidationError("No 'SignatureValue' element in the 'SignedInfo' element")

        # Check if the 'SignatureValue' element is valid
        try:
            signature_value = signature_metadata.find('SignatureValue').text
        except ET.ParseError:
            raise ValidationError("Invalid 'SignatureValue' element")

        # Verify the signature
        if public_key.verify(signature_value, signature):
            print("The signature is valid for the provided public key.")
        else:
            raise ValidationError("The signature is invalid for the provided public key.")
    except ET.ParseError:
        raise ValidationError("Invalid XML document.")
    except ValidationError as e:
        print(e)

