    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    import xml.etree.ElementTree as ET
    if document.startswith("{"):
        # JSON format
        try:
            return json.loads(document)
        except json.JSONDecodeError:
            logger.error("parse_diaspora_webfinger: invalid JSON format: %s", document)
            return None
    elif document.startswith("<") and document.endswith(">"):
        # XML format
        try:
            return {
                "links": ET.fromstring(document).findall("Link")
            }
        except ET.ParseError:
            logger.error("parse_diaspora_webfinger: invalid XML format: %s", document)
            return None
    else:
        logger.error("parse_diaspora_webfinger: unsupported webfinger format: %s", document)
        return None

