        """Resolves the include dict directive in the spec files. """
        include_rules = parser_dict.get('include', {})
        for key, value in iteritems(include_rules):
            if isinstance(value, dict):
                self._include_groups(value)
            else:
                parser_dict[key] = value

def _include_groups(self, parser_dict):
    """
    Resolves the include dict directive in the spec files.
    """
    for directive, content in iteritems(parser_dict):
        if isinstance(content, dict):
            if directive in ['env', 'os', 'common', 'module']:
                include_dict = content
                for key, value in iteritems(include_dict):
                    self.requirement_handler.load_remote_requirement(
                        key.replace('AZURE_', ''), value
                    )
        elif directive in ['git', 'github', 'src'] and content:
            self.requirement_handler.load_remote_requirement(directive, content)

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    for group in parser_dict.get('include', []):
        parser_dict.update(self._include_group(group))
    return parser_dict

