        for dep, new in attrs.items():
            if not hasattr(attrs, dep):
                print(f"Warning: Attribute '{dep}' does not exist.")
                return False
            elif not hasattr(attrs, new):
                print(f"Warning: Attribute '{new}' does not exist.")
                return False
            else:
                return True

    cli_deprecated = verify_deprecated_attributes(cli_args) if cli_args else True
    answer_file_deprecated = verify_deprecated_attributes(answer_file_args) if answer_file_args else True

    if not cli_deprecated and not answer_file_deprecated:
        print("No deprecated attributes found.")
    else:
        print("Deprecated attributes found.")
        if cli_args:
            print(f"CLI deprecated: {cli_args}")
        if answer_file_args:
            print(f"Answer file deprecated: {answer_file_args}")

