def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    for name, value in values_dict.items():
        parser = getattr(self.parser, parser_name)
        if parser.has_arg(name):
            value = self.parser._get_action_default(name)
            if not isinstance(parser._get_action_from_name(name), argparse.SwitchAction):
                value = parser._get_validated_action_state(parser._get_action_from_name(name), name, value)
            if parser._get_action_from_name(name).type == type([]):
                value = parser._get_typeconversion(None)(value)
            elif parser._get_action_from_name(name).type is bool:
                value = parser._get_typeconversion(None)(value)
            elif isinstance(parser._get_action_from_name(name).type, type(float)):
                value = parser._get_typeconversion(None)(value)
            elif isinstance(parser._get_action_from_name(name).type, type(int)):
                value = parser._get_typeconversion(None)(value)

            values_dict[name] = value

def _convert_non_cli_args(self, parser_name, values_dict):
    """
    Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    for arg_name, arg_value in values_dict.items():
        if arg_value is not None:
            types = getattr(self, parser_name + '_types').items()
            for type_name, type_cls in types:
                if isinstance(arg_value, type_cls):
                    values_dict[arg_name] = type_cls(arg_value)
                    break

